// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"ACT Science is really a reading-data test. You rarely need outside science knowledge. Let's learn the strategy.","blocks":[{"t":"key","text":"Since 2025, ACT Science is optional and scored separately from the composite. It has 40 questions in 40 minutes, so about one minute per question. Many colleges and scholarships still look at it, so check before skipping."},{"t":"p","text":"Most answers come directly from the graphs, tables and experiments in each passage."},{"t":"p","text":"Strategy:"},{"t":"list","items":["Skim the passage quickly; don't read every word.","Go straight to the questions and find the figure they point to.","Read axis labels, units and keys carefully.","Answer data questions first; save conflicting-viewpoints passages for last if they're slow for you."]}]},{"say":"ACT Science has three passage types. Recognizing them helps you attack each one.","blocks":[{"t":"key","text":"Data Representation passages present graphs and tables; questions ask you to read values and spot trends."},{"t":"p","text":"Research Summaries describe one or more experiments; questions ask about design, variables and results."},{"t":"p","text":"Conflicting Viewpoints present two or more hypotheses (like Scientist 1 and Scientist 2); questions ask what each believes and where they agree or disagree."},{"t":"p","text":"For conflicting viewpoints, summarize each viewpoint in one sentence in the margin before answering."},{"t":"tip","text":"Underline the key claim of each viewpoint. Most questions ask what one scientist would predict or how a new result affects a claim."},{"t":"lab","kind":"lab","title":"The classic pendulum passage","aim":"A student tests whether a pendulum's length, mass or swing angle affects its period. Run the experiments yourself.","sets":[{"name":"L","start":1,"label":"Length (m)","min":0.2,"max":2,"step":0.1},{"name":"m","start":100,"label":"Bob mass (g)","min":50,"max":500,"step":50}],"outs":[{"name":"T","expr":"2*pi*sqrt(L/g)","label":"Period (s)"}],"steps":["Experiment 1: change only the length and record 4 trials.","Experiment 2: change only the mass. Did the period change?"],"noise":1,"result":"Only length affects the period (T grows with √L); mass doesn't. ACT questions test this: identify the variable changed in each experiment and what stayed constant.","plot":{"x":"L","y":"T"}}]}],[{"say":"Most ACT Science points come from reading data accurately. Let's practice.","blocks":[{"t":"key","text":"To read a value, find the right row or line, then trace carefully to the matching value. Watch for different units and scales on multiple axes."},{"t":"p","text":"Trends: direct relationship (both increase), inverse relationship (one increases as the other decreases), or no clear trend."},{"t":"p","text":"Interpolation estimates values between data points; extrapolation estimates beyond the data by extending the trend."},{"t":"ex","problem":"A table shows plant height: week 1: 2 cm, week 2: 4 cm, week 3: 6 cm. Predict week 5.","steps":["It grows 2 cm per week"],"answer":"About 10 cm (extrapolating the trend)"},{"t":"lab","kind":"lab","title":"Solubility curves","aim":"Dissolve potassium nitrate and sodium chloride in 100 g of water at different temperatures and read their solubility.","sets":[{"name":"T","start":30,"label":"Water temperature (°C)","min":0,"max":80,"step":5}],"outs":[{"name":"KNO3","expr":"13.3*exp(0.0355*T)","label":"KNO₃ solubility (g/100 g water)"},{"name":"NaCl","expr":"35.7 + 0.04*T","label":"NaCl solubility (g/100 g water)"}],"steps":["Record both solubilities every 10 °C.","At what temperature are they equal? Which salt depends more on temperature?"],"noise":2,"result":"KNO₃ solubility rises steeply with temperature, while NaCl barely changes; the curves cross near 24 °C. ACT data questions ask you to read values, compare trends and interpolate between points.","plot":{"x":"T","y":"KNO3"}}]},{"say":"Harder questions combine information from two figures. Take it one step at a time.","blocks":[{"t":"key","text":"When a question uses two figures, find the shared variable that connects them. Use the first figure to get a value, then look it up in the second."},{"t":"p","text":"Watch for:"},{"t":"list","items":["Different units (mL vs. L, °C vs. K).","Logarithmic or uneven scales.","Keys and legends that distinguish multiple lines.","Questions that ask about a percent change or a ratio rather than a raw value."]},{"t":"ex","problem":"Figure 1 shows the temperature at each depth; Figure 2 shows the oxygen at each temperature. Find the oxygen at 20 m depth.","steps":["Figure 1: 20 m → 12°C"],"answer":"Figure 2: 12°C → read the oxygen value there"}]}],[{"say":"Research Summaries test whether you understand how experiments work.","blocks":[{"t":"key","text":"The independent variable is what scientists change on purpose. The dependent variable is what they measure. Controlled variables stay constant. A control group provides a baseline for comparison."},{"t":"p","text":"Questions may ask why a step was included, what would happen if a variable changed, or which experiment would test a new hypothesis."},{"t":"ex","problem":"Scientists test plant growth at 3 light levels with the same soil and water. Identify the variables.","steps":["Changed: light level (independent)","Measured: growth (dependent)"],"answer":"Controlled: soil and water"},{"t":"p","text":"To test a hypothesis, change only the variable in question and keep everything else the same."},{"t":"lab","kind":"lab","title":"Seed germination experiment","aim":"Design and run an experiment testing how temperature affects the percentage of radish seeds that germinate in 5 days.","sets":[{"name":"T","start":20,"label":"Temperature (°C)","min":0,"max":45,"step":1},{"name":"n","start":50,"label":"Seeds per dish","min":10,"max":100,"step":10}],"outs":[{"name":"G","expr":"95*exp(-((T - 25)/8)^2)","label":"Germination (%)"},{"name":"count","expr":"G/100*n","label":"Seeds germinated"}],"steps":["Independent variable: temperature. Dependent variable: percent germinated. Controls: seed type, water, light, number of seeds.","Record germination at 6 temperatures."],"noise":5,"result":"Germination peaks near 25 °C and falls at extremes. More seeds per dish reduces the effect of random variation. On the ACT, a good experiment changes only one variable and keeps everything else the same.","plot":{"x":"T","y":"G"}}]},{"say":"Conflicting Viewpoints and reasoning questions ask you to compare ideas and judge evidence.","blocks":[{"t":"key","text":"To evaluate a viewpoint, ask: what does it claim, what evidence supports it, and what would weaken it? Find where the viewpoints agree, which questions often target."},{"t":"p","text":"Questions may ask which new finding would support or weaken a scientist's view. A finding supports a view if it's consistent with that view's prediction."},{"t":"ex","problem":"Scientist 1 says a lake's fish died from low oxygen; Scientist 2 blames a toxin. Which finding supports Scientist 1?","steps":["Scientist 1 predicts low oxygen levels"],"answer":"Measurements showing very low dissolved oxygen when the fish died"}]}]];
export default text;
